import { readFileSync } from "node:fs"
import path from "node:path"
import { describe, expect, test } from "vitest"
import { quickStartPrompt, setupPrompt } from "./setup-prompts"

const promptsDir = path.join(
  import.meta.dirname,
  "../content/shared/setup-prompt"
)

function quickStartFile(name: string) {
  const source = readFileSync(path.join(promptsDir, `${name}.mdx`), "utf8")
  return source.match(/```text prompt\n([\s\S]*?)\n```/)?.[1]
}

const site = "https://ui-sdk.dev"

describe("setup prompts", () => {
  test.each(["react", "vue", "svelte", "solid", "web-components"] as const)(
    "rebuilds the %s Quick Start prompt word for word",
    (stackId) => {
      expect(quickStartPrompt(stackId)).toBe(quickStartFile(stackId))
    }
  )

  test("names the project and how to create it", () => {
    const prompt = setupPrompt({
      stackId: "svelte",
      projectId: "sveltekit",
      site,
    })
    expect(prompt).toMatch(
      /^Set up ui-sdk in this Svelte project with SvelteKit\. It needs Svelte 5\.33 or newer\.\n/
    )
    expect(prompt).toContain(
      "If the folder is empty, create the project first: npx sv create ."
    )
  })

  test("creates a Solid Vite app from Solid's starter with one copy of the core", () => {
    const prompt = setupPrompt({ stackId: "solid", projectId: "vite", site })
    expect(prompt).toContain(
      "create the project first: npm init solid@latest . -- --solid --ts --template bare --no-devtools\n"
    )
    expect(prompt).toContain(
      `2. Add optimizeDeps: { exclude: ["@ui-sdk/core"] } to vite.config.ts, so the app and @ui-sdk/solid share one copy of the core in development.\n3. Import the default styles once`
    )
  })

  test("imports web.css after installing", () => {
    const prompt = setupPrompt({ stackId: "react", projectId: "next", site })
    expect(prompt).toContain(
      `2. Import the default styles once at the app's entry: import "@ui-sdk/core/web.css". If the app uses Tailwind CSS, start its global stylesheet with these lines instead, in place of its own @import "tailwindcss", so Tailwind's base styles don't reset them:\n   @layer ui-sdk;\n   @import "tailwindcss";\n   @import "@ui-sdk/core/web.css" layer(components);\n`
    )
  })

  test("adds the module and web.css to nuxt.config.ts for Nuxt", () => {
    const prompt = setupPrompt({ stackId: "vue", projectId: "nuxt", site })
    expect(prompt).toContain(
      `2. Add "@ui-sdk/vue" to modules in nuxt.config.ts.\n3. Add the default styles once to css in nuxt.config.ts: css: ["@ui-sdk/core/web.css"]. If the app uses Tailwind CSS`
    )
  })

  test.each([
    ["web-components", "html"],
    ["artifacts", undefined],
  ])("loads web.js and web.css from the site for %s", (stackId, projectId) => {
    const prompt = setupPrompt({ stackId, projectId, site })
    expect(prompt).toContain(
      `<script type="module" src="https://ui-sdk.dev/web.js"></script>`
    )
    expect(prompt).toContain(
      `<link rel="stylesheet" href="https://ui-sdk.dev/web.css" />`
    )
    expect(prompt).toContain("read https://ui-sdk.dev/web.md.")
  })

  test("creates the project without prompts and checks the build", () => {
    const prompt = setupPrompt({ stackId: "vue", projectId: "nuxt", site })
    expect(prompt).toContain(
      "create the project first: npm create nuxt@latest . -- --template minimal --packageManager npm --no-gitInit --force\n"
    )
    expect(prompt).toMatch(
      /\n\d\. Run the project's build and make sure it passes\.\n\nWhen you're done/
    )
  })

  test("asks what to build once the setup is done", () => {
    expect(setupPrompt({ stackId: "solid", projectId: "start", site })).toMatch(
      /\n\nWhen you're done, ask me what I'd like to build\.$/
    )
  })
})

import { describe, expect, test } from "vitest"
import { createSearchIndex, searchIndex } from "./search"

const index = createSearchIndex([
  {
    url: "/docs/react/components/navigation-menu",
    title: "Navigation Menu",
    headings: [{ id: "keyboard", content: "Keyboard" }],
    contents: [
      { heading: "keyboard", content: "Arrow keys move between `MenuItem`s." },
    ],
  },
  {
    url: "/docs/react/components/menu",
    title: "Menu",
    headings: [{ id: "submenus", content: "Submenus" }],
    contents: [{ content: "A menu of actions." }],
  },
  {
    url: "/docs/react/components/slider",
    title: "Slider",
    headings: [],
    contents: [],
  },
])

describe("searchIndex", () => {
  test("ranks an exact title first and lists the page before its matches", () => {
    expect(searchIndex(index, "menu").map((result) => result.url)).toEqual([
      "/docs/react/components/menu",
      "/docs/react/components/menu#submenus",
      "/docs/react/components/menu",
      "/docs/react/components/navigation-menu",
      "/docs/react/components/navigation-menu#keyboard",
    ])
  })

  test("needs every term and marks each one", () => {
    expect(searchIndex(index, "arrow item")).toEqual([
      {
        id: "/docs/react/components/navigation-menu:0",
        type: "page",
        content: "Navigation Menu",
        url: "/docs/react/components/navigation-menu",
      },
      {
        id: "/docs/react/components/navigation-menu:1",
        type: "text",
        content:
          "<mark>Arrow</mark> keys move between `Menu<mark>Item</mark>`s.",
        url: "/docs/react/components/navigation-menu#keyboard",
      },
    ])
  })

  test("lists a heading once, and not when it repeats the page title", () => {
    const menubar = createSearchIndex([
      {
        url: "/docs/react/components/menubar",
        title: "Menubar",
        headings: [
          { id: "controller", content: "Controller" },
          { id: "data-attributes-menubar", content: "Menubar" },
          { id: "menubar", content: "Menubar" },
          { id: "controller-1", content: "Controller" },
        ],
        contents: [],
      },
    ])
    expect(searchIndex(menubar, "menubar").map((result) => result.url)).toEqual(
      ["/docs/react/components/menubar"]
    )
    expect(
      searchIndex(menubar, "controller").map((result) => result.url)
    ).toEqual([
      "/docs/react/components/menubar",
      "/docs/react/components/menubar#controller",
    ])
  })

  test("finds nothing for an empty query", () => {
    expect(searchIndex(index, "  ")).toEqual([])
  })
})

import { expect } from "@playwright/test"
import { test } from "../docs-test"
import { openExamples } from "./behaviors/helpers"

test("the rating's agent key lets an agent read it and rate", async ({
  page,
}) => {
  const { errors } = await openExamples(
    page,
    "/docs/agents/connect-an-agent/your-components"
  )
  const example = page.locator("[data-example]").first()
  await example.getByRole("button", { name: "Read the page" }).click()
  const output = example.getByRole("status")
  await expect(output).toContainText('"label": "Your rating"')
  await expect(output).toContainText('"rate"')
  await example.getByRole("button", { name: "Ask for 4 stars" }).click()
  await expect(output).toContainText('"ok": true')
  const stars = example.getByRole("group", { name: "Your rating" })
  await expect(stars.getByRole("button", { name: "4 stars" })).toHaveAttribute(
    "data-filled",
    ""
  )
  await expect(
    stars.getByRole("button", { name: "5 stars" })
  ).not.toHaveAttribute("data-filled")
  expect(errors).toEqual([])
})

type Node = {
  type: string
  lang?: string | null
  value?: string
  children?: Node[]
}

// Authors write npm or npx commands. Promote command blocks so remark-npm
// generates package-manager tabs, including when the fence has no language.
function remarkInstall() {
  return (tree: Node) => {
    const visit = (node: Node) => {
      if (
        node.type === "code" &&
        [
          undefined,
          null,
          "",
          "bash",
          "sh",
          "shell",
          "npm",
          "package-install",
        ].includes(node.lang) &&
        node.value
      ) {
        const lines = node.value.trim().split("\n")
        const commands = lines.filter((line) => line.trim())
        if (
          commands.length &&
          commands.every((line) =>
            /^(?:npm\s+|npx\s+|pnpm add\s+)\S/.test(line)
          )
        ) {
          node.lang = "npm"
          // The converter needs `install`; npm's `add` alias isn't supported.
          node.value = lines
            .map((line) =>
              line.replace(/^(?:npm add|pnpm add)\s+/, "npm install ")
            )
            .join("\n")
        }
      }
      node.children?.forEach(visit)
    }
    visit(tree)
  }
}

export { remarkInstall }

type Project = {
  id: string
  name: string
  create?: string
  needs?: string
  steps?: string[]
  styles?: string
}

type Stack = {
  id: string
  name: string
  pkg?: string
  needs?: string
  note?: string
  quickStart?: string[]
  projects: Project[]
}

const stacks = [
  {
    id: "react",
    name: "React",
    pkg: "react",
    needs: "It needs React 19 or newer.",
    projects: [
      {
        id: "next",
        name: "Next.js",
        create: "npx create-next-app@latest . --yes",
      },
      {
        id: "vite",
        name: "Vite",
        create: "npm create vite@latest . -- --template react-ts",
      },
      {
        id: "start",
        name: "TanStack Start",
        create: "npx @tanstack/cli@latest create . --framework react",
      },
    ],
  },
  {
    id: "vue",
    name: "Vue",
    pkg: "vue",
    needs: "It needs Vue 3.5 or newer.",
    quickStart: [
      `If it's a Nuxt 4 or newer app, add "@ui-sdk/vue" to modules in nuxt.config.ts.`,
    ],
    projects: [
      {
        id: "nuxt",
        name: "Nuxt",
        create:
          "npm create nuxt@latest . -- --template minimal --packageManager npm --no-gitInit --force",
        steps: [`Add "@ui-sdk/vue" to modules in nuxt.config.ts.`],
        styles: `Add the default styles once to css in nuxt.config.ts: css: ["@ui-sdk/core/web.css"]`,
      },
      {
        id: "vite",
        name: "Vite",
        create: "npm create vite@latest . -- --template vue-ts",
      },
    ],
  },
  {
    id: "svelte",
    name: "Svelte",
    pkg: "svelte",
    needs: "It needs Svelte 5.33 or newer.",
    projects: [
      {
        id: "sveltekit",
        name: "SvelteKit",
        create:
          "npx sv create . --template minimal --types ts --no-add-ons --install npm",
      },
      {
        id: "vite",
        name: "Vite",
        create: "npm create vite@latest . -- --template svelte-ts",
      },
    ],
  },
  {
    id: "solid",
    name: "Solid",
    pkg: "solid",
    needs: "It needs Solid 2: solid-js and @solidjs/web 2.0.0-rc.14 or newer.",
    projects: [
      {
        id: "vite",
        name: "Vite",
        create:
          "npm init solid@latest . -- --solid --ts --template bare --no-devtools",
        steps: [
          `Add optimizeDeps: { exclude: ["@ui-sdk/core"] } to vite.config.ts, so the app and @ui-sdk/solid share one copy of the core in development.`,
        ],
      },
      {
        id: "start",
        name: "TanStack Start",
        create: "npx @tanstack/cli@latest create . --framework solid",
        // The stable TanStack Start for Solid is on Solid 1.9; only its release
        // candidate supports Solid 2.
        needs:
          "It needs Solid 2: move solid-js, @solidjs/web and @tanstack/solid-start to their 2.0 release candidates, with solid-js and @solidjs/web 2.0.0-rc.14 or newer.",
      },
    ],
  },
  {
    id: "web-components",
    name: "Web Components",
    pkg: "web",
    needs:
      "Each component registers its tags when you import its entry, like @ui-sdk/web/dialog.",
    projects: [
      {
        id: "vite",
        name: "Vite",
        create: "npm create vite@latest . -- --template vanilla-ts",
      },
      { id: "html", name: "HTML" },
    ],
  },
  {
    id: "artifacts",
    name: "Artifacts",
    note: "Copy and paste the following prompt in Claude Code or Cowork.",
    projects: [],
  },
] satisfies Stack[]

type StackId = (typeof stacks)[number]["id"]

const skillStep =
  "If you support skills, run: npx skills add vercel-labs/ui --skill ui-sdk"
const tailwindStyles = `If the app uses Tailwind CSS, start its global stylesheet with these lines instead, in place of its own @import "tailwindcss", so Tailwind's base styles don't reset them:
   @layer ui-sdk;
   @import "tailwindcss";
   @import "@ui-sdk/core/web.css" layer(components);`
const closing = "When you're done, ask me what I'd like to build."

function findStack(id: string) {
  return stacks.find((stack) => stack.id === id) ?? stacks[0]
}

function steps(list: string[]) {
  return list.map((step, index) => `${index + 1}. ${step}`).join("\n")
}

function webTags(site: string) {
  return `   <script type="module" src="${site}/web.js"></script>\n   <link rel="stylesheet" href="${site}/web.css" />`
}

function agentsStep(docs: string) {
  return `Add a note to AGENTS.md, creating it if needed: before using ui-sdk, follow the ui-sdk skill if it's installed, and read ${docs}/llms.txt. To build a new component, also search ${docs}/core.md by heading, and read rendering.md next to it.`
}

function installStep(pkg: string) {
  return `Install @ui-sdk/${pkg} and @ui-sdk/core with the project's package manager. If a release-age policy blocks the install, stop and ask me instead of changing it.`
}

/** The Quick Start prompt for a framework, as content/shared/setup-prompt has it. */
function quickStartPrompt(stackId: StackId) {
  const stack = findStack(stackId)
  if (!stack.pkg) {
    return ""
  }
  return `Set up ui-sdk in this ${stack.name} project. ${stack.needs}

${steps([installStep(stack.pkg), ...(stack.quickStart ?? []), agentsStep(`node_modules/@ui-sdk/${stack.pkg}/docs`), skillStep])}`
}

function artifactPrompt(site: string) {
  return `Build this as a single HTML page with ui-sdk web components. Each component registers its tags the first time they appear on the page.

${steps([
  `Load ui-sdk with these two tags in the <head>. web.css gives every component its default styles:\n${webTags(site)}`,
  `Before you write any code, read ${site}/web.md.`,
  "Keep everything in that one file, with your styles in a <style> tag. Show me the whole file each time.",
])}`
}

function htmlPrompt(site: string) {
  return `Set up ui-sdk in this HTML project, with no build step. Each component registers its tags the first time they appear on the page.

${steps([
  `Add these two tags to the <head> of each page. web.css gives every component its default styles:\n${webTags(site)}`,
  `Add a note to AGENTS.md, creating it if needed: before using ui-sdk, follow the ui-sdk skill if it's installed, and read ${site}/web.md.`,
  skillStep,
])}`
}

function projectPrompt(stack: Stack & { pkg: string }, project: Project) {
  return `Set up ui-sdk in this ${stack.name} project with ${project.name}. ${project.needs ?? stack.needs}
If the folder is empty, create the project first: ${project.create}

${steps([
  installStep(stack.pkg),
  ...(project.steps ?? []),
  `${project.styles ?? `Import the default styles once at the app's entry: import "@ui-sdk/core/web.css"`}. ${tailwindStyles}`,
  agentsStep(`node_modules/@ui-sdk/${stack.pkg}/docs`),
  skillStep,
  "Run the project's build and make sure it passes.",
])}`
}

/**
 * The prompt the Copy Prompt dialog copies: the Quick Start prompt for the
 * framework, with the project's create command and web.css as its styles.
 */
function setupPrompt({
  stackId,
  projectId,
  site,
}: {
  stackId: string
  projectId?: string
  site: string
}) {
  const stack = findStack(stackId)
  const siteUrl = site.replace(/\/+$/, "")
  const project =
    stack.projects.find((item) => item.id === projectId) ?? stack.projects[0]
  const body = !stack.pkg
    ? artifactPrompt(siteUrl)
    : project.id === "html"
      ? htmlPrompt(siteUrl)
      : projectPrompt(stack, project)
  return `${body}\n\n${closing}`
}

export { quickStartPrompt, setupPrompt, type StackId, stacks }

