})

test("a toast's action and cancel buttons hear how they were pressed", () => {
  const sources: string[] = []
  const toaster = createToaster()
  mount(() => <ToastRegion toaster={toaster} />)
  toaster("Deleted", {
    duration: Infinity,
    action: {
      label: "Undo",
      onAction: (_event, { source }) => sources.push(`undo:${source}`),
    },
  })
  toaster("Saved", {
    duration: Infinity,
    cancel: {
      label: "Keep",
      onCancel: (_event, { source }) => sources.push(`keep:${source}`),
    },
  })
  flush()
  withSource("agent", () => buttonNamed("Undo").click())
  withSource("keyboard", () => buttonNamed("Keep").click())
  expect(sources).toEqual(["undo:agent", "keep:keyboard"])
})

import { afterEach, expect } from "vitest"

// jsdom has no Web Animations API and no layout: nothing animates, so every
// list is empty, and scrolling an element into view does nothing.
if (typeof Element !== "undefined") {
  Element.prototype.getAnimations ??= () => []
  Element.prototype.scrollIntoView ??= () => {}
}

// Options reach an instance from an effect. Anything else it writes while
// they're handed over would write the parts' `$state` inside that effect,
// which Svelte's docs say not to do. Core's development build records those
// writes as relays, and every test fails on one.
afterEach(() => {
  const history = (
    globalThis as Record<symbol, { relays?: unknown[] } | undefined>
  )[Symbol.for("ui-sdk.devtools.history@1")]
  const relays = history?.relays?.splice(0) ?? []
  expect(relays, "state written while options were handed over").toEqual([])
})

import { flushSync, mount, unmount } from "svelte"
import { afterEach, expect, test } from "vitest"
import { createToaster } from "../src/toast"
import App from "./apps/toast-action-app.svelte"

// jsdom has no ResizeObserver, which a toast measures itself with.
globalThis.ResizeObserver ??= class {
  observe() {}
  unobserve() {}
  disconnect() {}
}

let cleanup = () => {}
afterEach(() => {
  cleanup()
  document.body.replaceChildren()
})

test("an action with its own handler renders for a toast that has no action", () => {
  const log: string[] = []
  const toaster = createToaster<string>()
  const target = document.body.appendChild(document.createElement("div"))
  const app = mount(App, {
    target,
    props: { log: (entry: string) => log.push(entry), toaster },
  })
  cleanup = () => unmount(app)
  toaster("Saved", { duration: Infinity })
  flushSync()
  const action = document.querySelector<HTMLButtonElement>(
    '[data-slot="toast-action"]'
  )
  expect(action?.textContent).toBe("")
  action?.click()
  expect(log).toEqual(["action"])
})
